def per_project_links_to_gigs(apps, schema_editor):
    """Turn old per-project settings (fiverr_<slug>_gig) into one FiverrGig per link, then clear them."""
    SiteSetting = apps.get_model('content_app', 'SiteSetting')
    Project = apps.get_model('content_app', 'Project')
    FiverrGig = apps.get_model('content_app', 'FiverrGig')
    by_url = {}
    for setting in SiteSetting.objects.filter(key__startswith='fiverr_', key__endswith='_gig').exclude(value=''):
        slug = setting.key[len('fiverr_'):-len('_gig')]
        by_url.setdefault(setting.value.strip(), []).append(slug)
    for n, (url, slugs) in enumerate(by_url.items(), 1):
        gig = FiverrGig.objects.create(title=KNOWN_TITLES.get(url, f'Fiverr gig {n}'), url=url, order=n)
        gig.projects.set(Project.objects.filter(slug__in=slugs))
    SiteSetting.objects.filter(key__startswith='fiverr_', key__endswith='_gig').delete()


